const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const airport = ee.Geometry.Point([85.817, 20.244]); // Biju Patnaik Airport, Bhubaneswar
  const saheedNagar = ee.Geometry.Point([85.848691, 20.290813]);

  const aprilStart = '2019-04-01';
  const aprilEnd = '2019-04-30';
  const mayStart = '2019-05-01';
  const mayEnd = '2019-05-31';

  // 2. Data Acquisition & Check
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  const aprilCol = viirs.filterDate(aprilStart, aprilEnd);
  const mayCol = viirs.filterDate(mayStart, mayEnd);

  const aprilSize = aprilCol.size().getInfo();
  const maySize = mayCol.size().getInfo();

  console.log(`April 2019 Images: ${aprilSize}`);
  console.log(`May 2019 Images: ${maySize}`);

  if (aprilSize === 0 || maySize === 0) {
    console.log('No data for one or both months.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get monthly composites
  const aprilImg = aprilCol.first();
  const mayImg = mayCol.first();

  const band = 'avg_rad';

  // 4. Calculate brightness at both locations for both months
  const aprilAirport = aprilImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: airport,
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  const mayAirport = mayImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: airport,
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  const aprilSaheed = aprilImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: saheedNagar,
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  const maySaheed = mayImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: saheedNagar,
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  // 5. Validation & Final Answer
  if (aprilAirport === null || mayAirport === null || aprilSaheed === null || maySaheed === null) {
    console.log('Calculation failed - null values returned.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Airport - April: ${aprilAirport.toFixed(4)}, May: ${mayAirport.toFixed(4)}`);
  console.log(`Saheed Nagar - April: ${aprilSaheed.toFixed(4)}, May: ${maySaheed.toFixed(4)}`);

  const airportDecrease = aprilAirport - mayAirport;
  const saheedDecrease = aprilSaheed - maySaheed;

  console.log(`Airport decrease: ${airportDecrease.toFixed(4)}`);
  console.log(`Saheed Nagar decrease: ${saheedDecrease.toFixed(4)}`);

  if (airportDecrease > saheedDecrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
